  const FAVORITES_KEY = "wf_favorites";
  const REMOVE_ANIMATION_MS = 320;
  const WRAPPER_SYNC_DELAY_MS = 350;

  function getFavorites() {
    try {
      const stored = localStorage.getItem(FAVORITES_KEY);
      const parsed = JSON.parse(stored || "[]");
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  }

  function setFavorites(favorites) {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify(favorites));
  }

  function isFavorite(id) {
    return getFavorites().includes(id);
  }

  function addFavorite(id) {
    const favorites = getFavorites();
    if (!favorites.includes(id)) {
      favorites.push(id);
      setFavorites(favorites);
    }
  }

  function removeFavorite(id) {
    const favorites = getFavorites().filter(item => item !== id);
    setFavorites(favorites);
  }

  function formatFavoritesCount(count) {
    return count < 10 ? `0${count}` : `${count}`;
  }

  function popTickerText() {
    document.querySelectorAll(".h-ticker-text").forEach(el => {
      el.classList.remove("is-pop");
      void el.offsetWidth;
      el.classList.add("is-pop");
    });
  }

  function updateFavoriteButtons() {
    const favorites = getFavorites();

    document.querySelectorAll(".fav-toggle").forEach(button => {
      const id = button.getAttribute("data-fav-id");
      const active = id ? favorites.includes(id) : false;

      button.classList.toggle("is-favorite", active);
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });
  }

  function updateFavoritesCount(animate = false) {
    const count = getFavorites().length;
    const formattedCount = formatFavoritesCount(count);

    document.querySelectorAll(".h-ticker-text").forEach(el => {
      el.textContent = formattedCount;
    });

    document.querySelectorAll(".heart_ticker").forEach(el => {
      el.classList.toggle("is-visible", count > 0);
    });

    if (animate && count > 0) {
      popTickerText();
    }
  }

  function animateFavoriteItemOut(item) {
    if (!item || item.classList.contains("is-removing")) return;

    item.classList.add("is-removing");

    const itemHeight = item.offsetHeight;
    item.style.height = itemHeight + "px";
    item.style.overflow = "hidden";

    void item.offsetHeight;

    item.style.opacity = "0";
    item.style.transform = "scale(0.95) translateY(8px)";

    setTimeout(() => {
      item.style.height = "0px";
      item.style.marginTop = "0px";
      item.style.marginBottom = "0px";
      item.style.paddingTop = "0px";
      item.style.paddingBottom = "0px";
    }, 10);

    setTimeout(() => {
      item.style.display = "none";
    }, REMOVE_ANIMATION_MS);
  }

  function resetFavoriteItemIn(item) {
    if (!item) return;

    item.style.display = "";
    item.style.opacity = "1";
    item.style.transform = "scale(1) translateY(0)";
    item.style.height = "";
    item.style.marginTop = "";
    item.style.marginBottom = "";
    item.style.paddingTop = "";
    item.style.paddingBottom = "";
    item.style.overflow = "";
    item.classList.remove("is-removing");
  }

  function getVisibleFavItems(container) {
    return Array.from(container.querySelectorAll(".fav-item")).filter(item => {
      return getComputedStyle(item).display !== "none";
    });
  }

  function updateFavoritesWrappers() {
    document.querySelectorAll(".favorites_collection_wrapper").forEach(wrapper => {
      const dynLists = wrapper.querySelectorAll(".w-dyn-list");
      let wrapperHasVisibleItems = false;
      let wrapperHasFavItemsAtAll = false;

      dynLists.forEach(dynList => {
        const favItems = dynList.querySelectorAll(".fav-item");

        if (favItems.length > 0) {
          wrapperHasFavItemsAtAll = true;
        }

        const visibleItems = Array.from(favItems).filter(item => {
          return getComputedStyle(item).display !== "none";
        });

        const hasVisibleItems = visibleItems.length > 0;

        dynList.style.display = hasVisibleItems ? "" : "none";

        if (hasVisibleItems) {
          wrapperHasVisibleItems = true;
        }
      });

      // If this wrapper doesn't contain any favorite items at all,
      // leave it alone instead of force-hiding it.
      if (!wrapperHasFavItemsAtAll) {
        return;
      }

      wrapper.style.display = wrapperHasVisibleItems ? "" : "none";
    });
  }

  function updateFavoritesEmptyState() {
    const totalVisible = Array.from(document.querySelectorAll(".fav-item")).filter(item => {
      return getComputedStyle(item).display !== "none";
    }).length;

    document.querySelectorAll(".favorites-empty").forEach(el => {
      el.style.display = totalVisible === 0 ? "block" : "none";
    });
  }

  function updateFavoritesPage() {
    const favorites = getFavorites();
    const items = document.querySelectorAll(".fav-item");

    items.forEach(item => {
      const id = item.getAttribute("data-fav-id");
      const shouldShow = id && favorites.includes(id);

      if (shouldShow) {
        resetFavoriteItemIn(item);
      } else {
        animateFavoriteItemOut(item);
      }
    });

    setTimeout(() => {
      updateFavoritesWrappers();
      updateFavoritesEmptyState();
    }, WRAPPER_SYNC_DELAY_MS);
  }

  function toggleFavorite(id) {
    if (!id) return;

    if (isFavorite(id)) {
      removeFavorite(id);
    } else {
      addFavorite(id);
    }

    updateFavoriteButtons();
    updateFavoritesCount(true);

    if (document.body.classList.contains("page-favorites")) {
      updateFavoritesPage();
    }
  }

  document.addEventListener("click", function (event) {
    const button = event.target.closest(".fav-toggle");
    if (!button) return;

    event.preventDefault();
    event.stopPropagation();

    const id = button.getAttribute("data-fav-id");
    if (!id) return;

    toggleFavorite(id);
  });

  document.addEventListener("DOMContentLoaded", function () {
    updateFavoriteButtons();
    updateFavoritesCount(false);

    if (document.body.classList.contains("page-favorites")) {
      updateFavoritesPage();
    }

    setTimeout(() => {
      updateFavoriteButtons();
      updateFavoritesCount(false);

      if (document.body.classList.contains("page-favorites")) {
        updateFavoritesPage();
      }
    }, 300);
  });
